import{_ as i,a0 as o,w as r,s as d,ao as e,I as a,x as n,a1 as l,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"3 个 Python 模板库比较 | LCTT x X-CMD","titleTemplate":false,"description":"3 个 Python 模板库比较 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"3 个 Python 模板库比较 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"3 个 Python 模板库比较 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180427 3 Python template libraries compared","title":"3 个 Python 模板库比较","tag":"201806","desc":""},"relativePath":"201806/20180427 3 Python template libraries compared.md","filePath":"[post].md"}'),g={name:"201806/20180427 3 Python template libraries compared.md"};function h(u,s,m,f,y,b){const t=o("Link");return r(),d("div",null,[s[34]||(s[34]=e(`<h1 id="_3-个-python-模板库比较" tabindex="-1">3 个 Python 模板库比较 <a class="header-anchor" href="#_3-个-python-模板库比较" aria-label="Permalink to “3 个 Python 模板库比较”">​</a></h1><blockquote><p>你的下一个 Python 项目需要一个模板引擎来自动生成 HTML 吗？这有几种选择。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/library-libraries-search.png?itok=xH8xSU_G" alt=""></p><p>在我的日常工作中，我花费大量的时间将各种来源的数据转化为可读的信息。虽然很多时候这只是电子表格或某种类型的图表或其他数据可视化的形式，但也有其他时候，将数据以书面形式呈现是有意义的。</p><p>但我的头疼地方就是复制和粘贴。如果你要将数据从源头移动到标准化模板，则不应该复制和粘贴。这很容易出错，说实话，这会浪费你的时间。</p><p>因此，对于我定期发送的任何遵循一个共同的模式的信息，我倾向于找到某种方法来自动化至少一部分信息。也许这涉及到在电子表格中创建一些公式，一个快速 shell 脚本或其他解决方案，以便使用从外部源提取的信息自动填充模板。</p><p>但最近，我一直在探索 Python 模板来完成从其他数据集创建报告和图表的大部分工作。</p><p>Python 模板引擎非常强大。我的简化报告创建的使用案例仅仅触及了它的皮毛。许多开发人员正在利用这些工具来构建完整的 web 应用程序和内容管理系统。但是，你并不需要有一个复杂的 web 应用程序才能使用 Python 模板工具。</p><h3 id="为什么选择模板" tabindex="-1">为什么选择模板？ <a class="header-anchor" href="#为什么选择模板" aria-label="Permalink to “为什么选择模板？”">​</a></h3><p>每个模板工具都不甚相同，你应该阅读文档以了解其确切的用法。但让我们创建一个假设的例子。假设我想创建一个简短的页面，列出我最近编写的所有 Python 主题。就像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span>  &lt;head&gt;</span></span>
<span class="line"><span>    &lt;title&gt;My Python articles&lt;/title&gt;</span></span>
<span class="line"><span>  &lt;/head&gt;</span></span>
<span class="line"><span>  &lt;body&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &lt;p&gt;These are some of the things I have written about Python:&lt;/p&gt;</span></span>
<span class="line"><span>    &lt;ul&gt;</span></span>
<span class="line"><span>      &lt;li&gt;Python GUIs&lt;/li&gt;</span></span>
<span class="line"><span>      &lt;li&gt;Python IDEs&lt;/li&gt;</span></span>
<span class="line"><span>      &lt;li&gt;Python web scrapers&lt;/li&gt;</span></span>
<span class="line"><span>    &lt;/ul&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  &lt;/body&gt;</span></span>
<span class="line"><span>&lt;/html&gt;</span></span></code></pre></div><p>当它仅仅是这三个项目时，维护它是很简单的。但是当我想添加第四个、第五个或第六十七个时会发生什么？我可以从包含我所有页面列表的 CSV 文件或其他数据文件生成它，而不是手动编码此页面吗？我可以轻松地为我写的每个主题创建重复内容吗？我可以以编程方式更改每个页面上的文本标题吗？这就是模板引擎可以发挥作用的地方。</p>`,12)),a("p",null,[s[3]||(s[3]=n("有许多不同的选择，今天我将与你其中分享三个，顺序不分先后：",-1)),l(t,{href:"http://www.makotemplates.org/"},{default:p(()=>[...s[0]||(s[0]=[n("Mako",-1)])]),_:1}),s[4]||(s[4]=n("、 ",-1)),l(t,{href:"http://jinja.pocoo.org/"},{default:p(()=>[...s[1]||(s[1]=[n("Jinja2",-1)])]),_:1}),s[5]||(s[5]=n(" 和 ",-1)),l(t,{href:"https://genshi.edgewall.org/"},{default:p(()=>[...s[2]||(s[2]=[n("Genshi",-1)])]),_:1}),s[6]||(s[6]=n("。",-1))]),s[35]||(s[35]=a("h3",{id:"mako",tabindex:"-1"},[n("Mako "),a("a",{class:"header-anchor",href:"#mako","aria-label":"Permalink to “Mako”"},"​")],-1)),a("p",null,[l(t,{href:"http://www.makotemplates.org/"},{default:p(()=>[...s[7]||(s[7]=[n("Mako",-1)])]),_:1}),s[9]||(s[9]=n(" 是以 MIT 许可证发布的 Python 模板工具，专为快速展现而设计的（与 Jinja2 不同）。Reddit 已经使用 Mako 来展现他们的网页，它同时也是 Pyramid 和 Pylons 等 web 框架的默认模板语言。它相当简单且易于使用。你可以使用几行代码来设计模板；支持 Python 2.x 和 3.x，它是一个功能强大且功能丰富的工具，具有",-1)),l(t,{href:"http://docs.makotemplates.org/en/latest/"},{default:p(()=>[...s[8]||(s[8]=[n("良好的文档",-1)])]),_:1}),s[10]||(s[10]=n("，这一点我认为是必须的。其功能包括过滤器、继承、可调用块和内置缓存系统，这些系统可以被大型或复杂的 web 项目导入。",-1))]),s[36]||(s[36]=a("h3",{id:"jinja2",tabindex:"-1"},[n("Jinja2 "),a("a",{class:"header-anchor",href:"#jinja2","aria-label":"Permalink to “Jinja2”"},"​")],-1)),a("p",null,[s[12]||(s[12]=n("Jinja2 是另一个快速且功能全面的选项，可用于 Python 2.x 和 3.x，遵循 BSD 许可证。Jinja2 从功能角度与 Mako 有很多重叠，因此对于新手来说，你在两者之间的选择可能会归结为你喜欢的格式化风格。Jinja2 还将模板编译为字节码，并具有 HTML 转义、沙盒、模板继承和模板沙盒部分的功能。其用户包括 Mozilla、 SourceForge、 NPR、 Instagram 等，并且还具有",-1)),l(t,{href:"http://jinja.pocoo.org/docs/2.10/"},{default:p(()=>[...s[11]||(s[11]=[n("强大的文档",-1)])]),_:1}),s[13]||(s[13]=n("。与 Mako 在模板内部使用 Python 逻辑不同的是，Jinja2 使用自己的语法。",-1))]),s[37]||(s[37]=a("h3",{id:"genshi",tabindex:"-1"},[n("Genshi "),a("a",{class:"header-anchor",href:"#genshi","aria-label":"Permalink to “Genshi”"},"​")],-1)),a("p",null,[l(t,{href:"https://genshi.edgewall.org/"},{default:p(()=>[...s[14]||(s[14]=[n("Genshi",-1)])]),_:1}),s[15]||(s[15]=n(" 是我会提到的第三个选择。它是一个 XML 工具，具有强大的模板组件，所以如果你使用的数据已经是 XML 格式，或者你需要使用网页以外的格式，Genshi 可能成为你的一个很好的解决方案。HTML 基本上是一种 XML（好吧，不是精确的，但这超出了本文的范围，有点卖弄学问了），因此格式化它们非常相似。由于我通常使用的很多数据都是 XML 或其他类型的数据，因此我非常喜欢使用我可以用于多种事物的工具。",-1))]),s[38]||(s[38]=e(`<p>发行版目前仅支持 Python 2.x，尽管 Python 3 支持存在于主干中，但我提醒你，它看起来并没有得到有效的开发。Genshi 遵循 BSD 许可证提供。</p><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h3><p>因此，在上面的假设示例中，我不会每次写新主题时都更新 HTML 文件，而是通过编程方式对其进行更新。我可以创建一个模板，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span>  &lt;head&gt;</span></span>
<span class="line"><span>    &lt;title&gt;My Python articles&lt;/title&gt;</span></span>
<span class="line"><span>  &lt;/head&gt;</span></span>
<span class="line"><span>  &lt;body&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &lt;p&gt;These are some of the things I have written about Python:&lt;/p&gt;</span></span>
<span class="line"><span>    &lt;ul&gt;</span></span>
<span class="line"><span>      %for topic in topics:</span></span>
<span class="line"><span>      &lt;li&gt;\${topic}&lt;/li&gt;</span></span>
<span class="line"><span>      %endfor</span></span>
<span class="line"><span>    &lt;/ul&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  &lt;/body&gt;</span></span>
<span class="line"><span>&lt;/html&gt;</span></span></code></pre></div><p>然后我可以使用我的模板库来迭代每个主题，比如使用 Mako，像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from mako.template import Template</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mytemplate = Template(filename=&#39;template.txt&#39;)</span></span>
<span class="line"><span>print(mytemplate.render(topics=(&quot;Python GUIs&quot;,&quot;Python IDEs&quot;,&quot;Python web scrapers&quot;)))</span></span></code></pre></div><p>当然，在现实世界的用法中，我不会将这些内容手动地列在变量中，而是将它们从外部数据源（如数据库或 API）中提取出来。</p>`,7)),a("p",null,[s[17]||(s[17]=n("这些不是仅有的 Python 模板引擎。如果你正在开始创建一个将大量使用模板的新项目，那么你考虑的可能不仅仅是这三种选择。在 ",-1)),l(t,{href:"https://wiki.python.org/moin/Templating"},{default:p(()=>[...s[16]||(s[16]=[n("Python 维基",-1)])]),_:1}),s[18]||(s[18]=n("上查看更全面的列表，以获得更多值得考虑的项目。",-1))]),s[39]||(s[39]=a("hr",null,null,-1)),a("p",null,[s[20]||(s[20]=n("via: ",-1)),l(t,{href:"https://opensource.com/resources/python/template-libraries"},{default:p(()=>[...s[19]||(s[19]=[n("https://opensource.com/resources/python/template-libraries",-1)])]),_:1})]),a("p",null,[s[25]||(s[25]=n("作者：",-1)),l(t,{href:"https://opensource.com/users/jason-baker"},{default:p(()=>[...s[21]||(s[21]=[n("Jason Baker",-1)])]),_:1}),s[26]||(s[26]=n(" 选题：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[22]||(s[22]=[n("lujun9972",-1)])]),_:1}),s[27]||(s[27]=n(" 译者：",-1)),l(t,{href:"https://github.com/MjSeven"},{default:p(()=>[...s[23]||(s[23]=[n("MjSeven",-1)])]),_:1}),s[28]||(s[28]=n(" 校对：",-1)),l(t,{href:"https://github.com/wxy"},{default:p(()=>[...s[24]||(s[24]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[31]||(s[31]=n("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[29]||(s[29]=[n("LCTT",-1)])]),_:1}),s[32]||(s[32]=n(" 原创编译，",-1)),l(t,{href:"https://linux.cn/"},{default:p(()=>[...s[30]||(s[30]=[n("Linux中国",-1)])]),_:1}),s[33]||(s[33]=n(" 荣誉推出",-1))])])}const x=i(g,[["render",h]]);export{T as __pageData,x as default};
